
function createBookForm(){return LIBRA_CONFIG.useMock?'':`<details class="panel book-create"><summary>＋ Thêm sách mới</summary><form id="create-book-form"><p>Nhập thông tin sách. Các mục có dấu * là bắt buộc.</p><div class="form-grid">${[['title','Tên sách *',255],['author','Tác giả',255],['publisher','Nhà xuất bản',255],['isbn','ISBN',50],['category','Thể loại',100]].map(([name,label,max])=>`<label class="field">${label}<input name="${name}" maxlength="${max}" ${name==='title'?'required':''}></label>`).join('')}<label class="field">Giá bán (₫) *<input name="price" type="number" min="0" step="1" required></label><label class="field">Số lượng tồn kho *<input name="stockQuantity" type="number" min="0" max="2147483647" step="1" value="0" required></label><label class="field">Đường dẫn ảnh bìa<input name="imageUrl" type="url" maxlength="500" placeholder="https://..."></label></div><label class="field">Mô tả<textarea name="description" rows="4"></textarea></label><p class="form-error" role="alert"></p><button class="button" type="submit">Thêm sách</button> <button class="button secondary" type="reset">Nhập lại</button></form></details>`;}
function workStatusOptions(o){if(LIBRA_CONFIG.useMock)return ['Đã tiếp nhận','Đang giao','Hoàn tất','Đã hủy'].map(s=>`<option ${o.status.startsWith(s)?'selected':''}>${s}</option>`).join('');const next={PENDING_PAYMENT:['CANCELLED'],PENDING_CONFIRMATION:['CONFIRMED','PROCESSING','CANCELLED'],PAID:['CONFIRMED','PROCESSING','CANCELLED'],CONFIRMED:['PROCESSING','SHIPPING','CANCELLED'],PROCESSING:['SHIPPING','CANCELLED'],SHIPPING:['DELIVERED','RETURNED'],DELIVERED:['RETURNED']};return [o.statusCode,...(next[o.statusCode]||[])].map(s=>`<option value="${s}" ${o.statusCode===s?'selected':''}>${esc(LibraAPI.statuses[s]||s)}</option>`).join('');}
let workspaceOrders=[], workspacePath='';
function workNav(path){return `<nav class="work-nav">${(user.role==='admin'?['/quan-tri','/quan-ly','/nhan-vien']:user.role==='manager'?['/quan-ly','/nhan-vien']:['/nhan-vien']).map(p=>`<a class="${p===path?'active':''}" href="#${p}">${{'/quan-tri':'Quản trị hệ thống','/quan-ly':'Quản lý kinh doanh','/nhan-vien':'Xử lý đơn hàng'}[p]}</a>`).join('')}<a href="#/tai-khoan">Tài khoản & đăng xuất</a></nav>`;}
function orderRows(orders){return orders.length?orders.map(o=>`<form class="panel admin-order" data-order-edit="${esc(o.id)}"><div class="order-heading"><h3>${esc(o.id)}</h3><b>${money(o.total)}</b></div><p>${new Date(o.createdAt).toLocaleString('vi-VN')} · <span class="order-state ${o.status==='Hoàn tất'?'complete':o.status==='Đang giao'?'shipping':o.status==='Đã hủy'?'cancelled':''}">${esc(o.status)}</span></p><p>${o.items.map(i=>`${esc(i.title)} × ${i.quantity}`).join(' · ')}</p><label>Trạng thái <select name="status">${workStatusOptions(o)}</select></label> <button class="button" type="submit">Cập nhật đơn</button><p class="form-error" role="status"></p></form>`).join(''):'<div class="panel">Không có đơn hàng phù hợp.</div>';}
function metrics(items){return `<div class="work-metrics">${items.map(([label,value])=>`<div class="panel"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`;}
async function renderAdmin(version,path=(location.hash.slice(1).split('?')[0])){
 workspacePath=path;
 if(!user){main.innerHTML=empty('Đăng nhập để tiếp tục','Khu vực làm việc dành cho nhân sự Libra.','#/dang-nhap','Đăng nhập');return;}
 const allowed={'/quan-tri':['admin'],'/quan-ly':['admin','manager'],'/nhan-vien':['admin','manager','staff']};
 if(!allowed[path]?.includes(user.role)){main.innerHTML=empty('Bạn không có quyền truy cập','Vui lòng sử dụng khu vực tương ứng với vai trò của mình.',roleHome(user.role),'Về khu vực của tôi');return;}
 main.innerHTML='<section class="wrap section" role="status">Đang tải khu vực làm việc…</section>';
 try{
 const title={'/quan-tri':'Quản trị hệ thống','/quan-ly':'Quản lý kinh doanh','/nhan-vien':'Bàn làm việc nhân viên'}[path];
 let content='';
 if(path==='/quan-tri'){
 const accounts=await LibraAPI.accounts();if(version!==routeVersion)return;
 content=metrics([['Tài khoản',accounts.length],['Đang hoạt động',accounts.filter(a=>a.active).length],['Vai trò',4]])+`${createBookForm()}<h2>Tài khoản & phân quyền</h2><p>Thay đổi vai trò hoặc khóa tài khoản. Tài khoản đang đăng nhập được bảo vệ khỏi thao tác tự khóa.</p><div class="admin-books">${accounts.map(a=>`<form class="panel" data-account-edit="${esc(a.id)}"><span class="account-avatar" aria-hidden="true">${esc(a.name.slice(0,1))}</span><span class="role-badge ${esc(a.role)}">${roleName(a.role)}</span><h3>${esc(a.name)}</h3><p>${esc(a.email)}</p><label class="field">Vai trò<select name="role" ${a.id===user.id?'disabled':''}>${['customer','staff','manager','admin'].map(r=>`<option value="${r}" ${a.role===r?'selected':''}>${roleName(r)}</option>`).join('')}</select></label><label class="check"><input name="active" type="checkbox" ${a.active?'checked':''} ${a.id===user.id?'disabled':''}> Cho phép đăng nhập</label><button class="button" type="submit" ${a.id===user.id?'disabled':''}>Lưu quyền</button><p class="form-error" role="status"></p></form>`).join('')}</div><h2>Phạm vi quyền</h2><div class="panel"><p><b>Nhân viên:</b> tra cứu sách, xem và xử lý đơn.</p><p><b>Quản lý:</b> quyền nhân viên, thêm sách, sửa giá/tồn kho, xem tổng hợp kinh doanh.</p><p><b>Quản trị viên:</b> toàn bộ quyền quản lý và quản lý tài khoản.</p><p><b>Khách hàng:</b> mua sách và xem đơn của mình.</p></div>`;
 }else{
 workspaceOrders=await LibraAPI.workOrders();if(version!==routeVersion)return;
 if(path==='/quan-ly'){
 content=metrics([['Doanh thu đơn hoàn tất',money(workspaceOrders.filter(o=>o.status==='Hoàn tất').reduce((sum,o)=>sum+o.total,0))],['Tổng đơn hàng',workspaceOrders.length],['Sách sắp hết (≤ 5)',books.filter(b=>b.stock<=5).length]])+`${createBookForm()}<h2>Giá bán & tồn kho</h2><div class="admin-books">${books.map(b=>`<form class="panel admin-book" data-book-edit="${b.id}"><h3>${esc(b.title)}</h3><label class="field">Giá bán (₫)<input type="number" name="price" min="1" step="1" required value="${b.price}"></label><label class="field">Tồn kho<input type="number" name="stock" min="0" step="1" required value="${b.stock}"></label><button class="button" type="submit">Lưu sách</button><p class="form-error" role="status"></p></form>`).join('')}</div>`;
 }else{
 content=metrics([['Chờ xử lý',workspaceOrders.filter(o=>(o.status.startsWith('Đã tiếp nhận')||o.statusCode==='PENDING_CONFIRMATION')).length],['Đang giao',workspaceOrders.filter(o=>o.status==='Đang giao').length],['Hoàn tất',workspaceOrders.filter(o=>o.status==='Hoàn tất').length]])+`<details class="panel"><summary>Tra cứu giá & tồn kho (chỉ xem)</summary><div class="stock-list">${books.map(b=>`<p><b>${esc(b.title)}</b><span>${money(b.price)} · ${b.stock} cuốn</span></p>`).join('')}</div></details>`;
 }
 content+=`<h2>Đơn hàng</h2><form id="work-filter" class="work-filter"><label>Tìm đơn<input name="query" placeholder="Mã đơn hoặc tên sách"></label><label>Trạng thái<select name="status"><option value="">Tất cả</option>${(LIBRA_CONFIG.useMock?['Đã tiếp nhận','Đang giao','Hoàn tất','Đã hủy']:Object.values(LibraAPI.statuses)).map(s=>`<option>${s}</option>`).join('')}</select></label><button class="button">Lọc đơn</button></form><div id="work-orders">${orderRows(workspaceOrders)}</div>`;
 }
 main.innerHTML=`<section class="wrap section">${heading(title,`Xin chào ${esc(user.name)} · ${roleName(user.role)}`)}${workNav(path)}${LIBRA_CONFIG.useMock?'<p class="notice">Không gian làm việc demo • Thay đổi lưu trên trình duyệt này.</p>':''}${content}</section>`;document.title=title+' | Libra';window.scrollTo(0,0);
 }catch(error){if(version===routeVersion)main.innerHTML=empty('Không thể tải khu vực làm việc',esc(error.message),'#/tai-khoan','Về tài khoản');}
}
document.addEventListener('submit',async event=>{
 const form=event.target;
 if(form.id==='work-filter'){event.preventDefault();const data=new FormData(form),q=normalize(data.get('query')),status=data.get('status');document.querySelector('#work-orders').innerHTML=orderRows(workspaceOrders.filter(o=>(!status||o.status.startsWith(status))&&normalize(o.id+' '+o.items.map(i=>i.title).join(' ')).includes(q)));return;}
 if(form.id==='create-book-form'){event.preventDefault();if(form.dataset.saving)return;const message=form.querySelector('.form-error'),button=form.querySelector('[type=submit]');message.textContent='';try{if(!['admin','manager'].includes(user?.role))throw new Error('Bạn không có quyền thêm sách.');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));for(const key of Object.keys(data))data[key]=data[key].trim();if(!data.title)throw new Error('Vui lòng nhập tên sách.');data.price=Number(data.price);data.stockQuantity=Number(data.stockQuantity);data.isActive=true;if(!Number.isFinite(data.price)||data.price<0||!Number.isInteger(data.stockQuantity)||data.stockQuantity<0)throw new Error('Giá và tồn kho không hợp lệ.');if(data.imageUrl&&!/^https?:\/\//i.test(data.imageUrl))throw new Error('Đường dẫn ảnh phải bắt đầu bằng http:// hoặc https://.');form.dataset.saving='true';button.disabled=true;const book=await LibraAPI.createBook(data);books.push(book);if(!categories.includes(book.category))categories.push(book.category);form.reset();toast('Đã thêm sách: '+book.title);if(form.isConnected)await renderAdmin(routeVersion,workspacePath);}catch(error){message.textContent=error.message;}finally{delete form.dataset.saving;button.disabled=false;}return;}
 if(!form.dataset.bookEdit&&!form.dataset.orderEdit&&!form.dataset.accountEdit)return;event.preventDefault();
 const button=form.querySelector('button'),message=form.querySelector('.form-error');button.disabled=true;
 try{const data=new FormData(form);
 if(form.dataset.bookEdit){if(!['admin','manager'].includes(user?.role))throw new Error('Bạn không có quyền sửa sách.');await LibraAPI.updateBook(Number(form.dataset.bookEdit),{price:Number(data.get('price')),stock:Number(data.get('stock'))});books=await LibraAPI.books();await renderAdmin(routeVersion,workspacePath);toast('Đã lưu giá và tồn kho.');}
 else if(form.dataset.accountEdit){if(user?.role!=='admin')throw new Error('Bạn không có quyền phân quyền.');await LibraAPI.updateAccount(form.dataset.accountEdit,{role:data.get('role'),active:data.has('active')});message.textContent='Đã lưu quyền và trạng thái tài khoản.';}
 else{if(!['admin','manager','staff'].includes(user?.role))throw new Error('Bạn không có quyền xử lý đơn.');await LibraAPI.updateOrder(form.dataset.orderEdit,data.get('status'));await renderAdmin(routeVersion,workspacePath);toast('Đã cập nhật đơn.');}
 }catch(error){message.textContent=error.message;}finally{button.disabled=false;}
});
